import numpy as np

def trapezium(f, a, b, n):
    x = np.linspace(a, b, n + 1)
    y = f(x)
    h = (b - a) / n
    return float(h * (y.sum() - 0.5 * (y[0] + y[-1])))

def simpson(f, a, b, n):
    if n % 2:
        raise ValueError('n must be even')
    x = np.linspace(a, b, n + 1)
    y = f(x)
    h = (b - a) / n
    return float(h / 3 * (y[0] + y[-1] + 4 * y[1:-1:2].sum() + 2 * y[2:-1:2].sum()))

def observed_order(f, a, b, exact, rule, ns):
    e = [abs(rule(f, a, b, n) - exact) for n in ns]
    return float(np.log2(e[-2] / e[-1]))

def richardson(t_n, t_2n, p):
    return (2 ** p * t_2n - t_n) / (2 ** p - 1)
